let raw = msg.payload;
if (typeof raw !== 'string') {
    raw = JSON.stringify(raw);
}
raw = raw.trim();

// Format: FEAT,a_total,g_total,a_max,a_min,g_mean,a_std,g_max,ax,ay,az,model_pred,triage_pred,hr,spo2,temp
if (!raw.startsWith("FEAT,")) {
    return null;
}

const parts = raw.split(',').map(s => s.trim());
if (parts.length < 13) {
    return null;
}

const a_total = parseFloat(parts[1]) || 1.0;
const g_total = parseFloat(parts[2]) || 0.0;
const a_max   = parseFloat(parts[3]) || 1.0;
const a_min   = parseFloat(parts[4]) || 1.0;
const g_mean  = parseFloat(parts[5]) || 0.0;
const a_std   = parseFloat(parts[6]) || 0.0;
const g_max   = parseFloat(parts[7]) || 0.0;
const ax      = parseFloat(parts[8]) || 0.0;
const ay      = parseFloat(parts[9]) || 0.0;
const az      = parseFloat(parts[10]) || 1.0;
const model_pred  = parseInt(parts[11]) || 0;
const triage_pred = parseInt(parts[12]) || 0;

const hr   = (parts.length > 13) ? parseInt(parts[13]) || 0 : 0;
const spo2 = (parts.length > 14) ? parseInt(parts[14]) || 0 : 0;
const temp = (parts.length > 15) ? parseFloat(parts[15]) || 36.6 : 36.6;

const triageInfo = {
    0: { code: 0, label: "HIJAU - Normal", status: "NORMAL", color: "#10B981", badge: "pill-green" },
    1: { code: 1, label: "KUNING - Kerja Aktif", status: "KERJA_AKTIF", color: "#F59E0B", badge: "pill-amber" },
    2: { code: 2, label: "ORANYE - Waspada Dini", status: "WASPADA_DINI", color: "#F97316", badge: "pill-orange" },
    3: { code: 3, label: "MERAH - Darurat SOS", status: "DARURAT_JATUH", color: "#EF4444", badge: "pill-red" },
    4: { code: 4, label: "STANDBY - Jam Dilepas", status: "STANDBY", color: "#94A3B8", badge: "pill-gray" }
};

const tri = triageInfo[triage_pred] || triageInfo[0];

const telemetry = {
    device_id: "RESCUE-TAG-02",
    worker_id: "WRK-002",
    worker_name: "Agus Salim",
    sector: "Sektor 7 (Lorong C-4)",
    location: {
        name: "Sektor 7 (C-4 Level -120m)",
        lat: -8.2498,
        lng: 113.7012
    },
    triage: {
        code: triage_pred,
        label: tri.label,
        status: tri.status,
        color: tri.color,
        is_emergency: (triage_pred === 3)
    },
    vitals: {
        hr: hr,
        spo2: spo2,
        temp: temp,
        hr_text: (hr > 0) ? hr + " BPM" : "Mengukur...",
        spo2_text: (spo2 > 0) ? spo2 + "%" : "--%",
        temp_text: temp.toFixed(1) + "°C"
    },
    kinematics: {
        a_total: a_total,
        g_total: g_total,
        a_max: a_max,
        a_min: a_min,
        g_mean: g_mean,
        a_std: a_std,
        g_max: g_max,
        tinyml_pred: model_pred
    },
    network: {
        route: "1-Hop LoRa Relay via Jam #01",
        rssi: -68,
        frequency: 433.0
    },
    timestamp: new Date().toISOString()
};

msg.payload = telemetry;
msg.topic = "rescue/tag/data";

if (triage_pred === 3) {
    const alertMsg = {
        topic: "rescue/tag/alert",
        payload: {
            alert_type: "SOS_FALL_CRITICAL",
            worker: "Agus Salim (Jam Tangan #02)",
            sector: "Sektor 7 (C-4)",
            triage: telemetry.triage,
            vitals: hr + " BPM · " + spo2 + "% SpO2 · " + temp + "°C",
            kinematics: "Benturan " + a_max.toFixed(2) + "g + Imobilitas >30s",
            timestamp: telemetry.timestamp
        }
    };
    return [msg, alertMsg];
}

return [msg, null];
